def choose_move(observation):
    def sgn(v):
        return 1 if v > 0 else (-1 if v < 0 else 0)

    def clamp_move(dx, dy):
        dx = 1 if dx > 1 else (-1 if dx < -1 else dx)
        dy = 1 if dy > 1 else (-1 if dy < -1 else dy)
        return [dx, dy]

    def pos(v, fallback=(0, 0)):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            return v[0], v[1]
        return fallback

    def dist(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    env = observation.get("environment_name", "")
    sx, sy = pos(observation.get("self_position"))
    ox, oy = pos(observation.get("opponent_position"), (sx, sy))
    gw = observation.get("grid_width", 0) or 0
    gh = observation.get("grid_height", 0) or 0

    # Common data
    resources = observation.get("resources") or []
    unclaimed = observation.get("unclaimed_cells") or []
    opp_territory = observation.get("opponent_territory") or []
    self_territory = observation.get("self_territory") or []

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            # Chase but avoid pointless overlap if already adjacent.
            dx = sgn(ox - sx)
            dy = sgn(oy - sy)
            if dx != 0 and dy != 0:
                # Prefer axis that reduces distance while being simple/robust.
                if dist((sx + dx, sy), (ox, oy)) <= dist((sx, sy + dy), (ox, oy)):
                    dy = 0
                else:
                    dx = 0
            return clamp_move(dx, dy)
        # evader: move away from opponent, with slight preference for center if tied
        candidates = []
        for dx in (-1, 0, 1):
            for dy in (-1, 0, 1):
                score = dist((sx + dx, sy + dy), (ox, oy))
                if gw and gh:
                    cx = (gw - 1) / 2.0
                    cy = (gh - 1) / 2.0
                    score += -0.05 * (abs((sx + dx) - cx) + abs((sy + dy) - cy))
                candidates.append((score, dx, dy))
        candidates.sort(reverse=True)
        return [candidates[0][1], candidates[0][2]]

    if env == "territory_control":
        targets = unclaimed if unclaimed else opp_territory
        if not targets:
            # If nothing to claim, spread toward center or away from opponent.
            if gw and gh:
                tx, ty = (gw - 1) // 2, (gh - 1) // 2
            else:
                tx, ty = sx, sy
            if dist((sx, sy), (ox, oy)) <= 2:
                tx, ty = sx - sgn(ox - sx), sy - sgn(oy - sy)
            return clamp_move(sgn(tx - sx), sgn(ty - sy))
        best = None
        best_score = None
        for t in targets:
            p = pos(t)
            score = dist((sx, sy), p)
            # Prefer targets not too close to opponent when equal.
            score2 = dist((ox, oy), p)
            cur = (score, -score2)
            if best_score is None or cur < best_score:
                best_score = cur
                best = p
        return clamp_move(sgn(best[0] - sx), sgn(best[1] - sy))

    # resource_collection and any unknown mode
    if resources:
        # Prefer nearer resource, but break ties by moving away from opponent if needed.
        best = None
        best_key = None
        for r in resources:
            p = pos(r)
            key = (dist((sx, sy), p), dist((ox, oy), p))
            if best_key is None or key < best_key:
                best_key = key
                best = p
        dx = sgn(best[0] - sx)
        dy = sgn(best[1] - sy)
        # If opponent is closer to the same resource, sidestep a bit.
        if dist((ox, oy), best) <= dist((sx, sy), best) and dist((sx, sy), best) <= 2:
            if abs(best[0] - sx) >= abs(best[1] - sy):
                dy = sgn(sy - oy)
                if dy == 0:
                    dy = 1 if sy < gh - 1 else -1
            else:
                dx = sgn(sx - ox)
                if dx == 0:
                    dx = 1 if sx < gw - 1 else -1
        return clamp_move(dx, dy)

    # No resources visible: drift toward opponent or center depending on distance.
    if dist((sx, sy), (ox, oy)) <= 2:
        return clamp_move(sgn(sx - ox), sgn(sy - oy))
    if gw and gh:
        return clamp_move(sgn((gw - 1) / 2.0 - sx), sgn((gh - 1) / 2.0 - sy))
    return [0, 0]

